<?php
namespace App\Http\Controllers;
use App\Models\House;
class PublicController extends Controller { public function home(){return view('public.home',['total'=>House::where('is_public',true)->whereIn('status',['verified','published'])->count()]);} public function map(){return view('public.map');} public function statistics(){ $q=House::where('is_public',true)->whereIn('status',['verified','published']); return view('public.statistics',['total'=>$q->count(),'years'=>$q->selectRaw('survey_year,count(*) total')->groupBy('survey_year')->orderBy('survey_year')->get()]); } public function datasets(){return view('public.datasets');} public function viewer(){return view('public.viewer');} public function detail(House $house){abort_unless($house->is_public && in_array($house->status,['verified','published'],true),404);$house->load('region','structure','floor','ceiling','wall','roof','sanitation','utility','latestAssessment');return view('public.detail',['house'=>$house]);} }
